{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "In monkeys, the high-transfer analogue [18F]3 showed high brain uptake on PET, directly demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "The N-methyl-tetrahydropyridine analogue [11C]PHXY freely crossed the BBB in rodents and non-human primates after i.v. injection, directly supporting CNS access for the query's tetrahydropyridine motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "In mice, [125I]9Pe6IP achieved 5.3% ID/g brain uptake at 1 min after i.v. injection, a high brain-penetration phenotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "[18F]MC225, despite being a weak P-gp substrate, showed relatively high baseline brain uptake, indicating that weak efflux liability does not preclude meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Bupivacaine, a basic amine anaesthetic, produced detectable free brain concentrations >70 ng/g after subcutaneous dosing, showing that basic amines can achieve meaningful free brain exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Strong, transferable in vivo evidence from multiple high-scoring analogues shows high brain uptake, free brain exposure, and BBB penetration despite basic amine/efflux features; therefore the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct human CSF/plasma or brain-to-plasma ratio for the exact query molecule",
    "P-gp/BCRP efflux ratio not directly measured for the query",
    "Metabolic instability of the tetrahydropyridine ring not assessed"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

